<script setup lang="ts">
import {ref} from 'vue'
import {onLoad} from '@dcloudio/uni-app'
import PageShell from '../../../components/PageShell.vue'
import AppIcon from '../../../components/AppIcon.vue'
import StatePanel from '../../../components/StatePanel.vue'
import ReportCard from '../../../components/ReportCard.vue'
import TrendChart from '../../../components/TrendChart.vue'
import {healthApi} from '../../../api/health'
import {usePageData} from '../../../utils/usePageData'
import {go} from '../../../utils/navigation'
import type {Archive} from '../../../types'
const data=ref<Archive>(),active=ref(0),trendIndex=ref(0)
const {loading,error,load}=usePageData('worker',async()=>{data.value=await healthApi.archive()})
onLoad(q=>{if(q?.trend)active.value=1})
</script>
<template><PageShell title="健康档案" :back="false" tab="archive"><view class="content"><StatePanel :loading="loading" :error="error" @retry="load"/><template v-if="data"><view class="card archive-person"><image src="/static/miner.png" class="avatar"/><view class="grow"><view class="flex gap"><text class="person-name">{{data.profile.name}}</text><text class="tag">职工</text></view><text class="person-meta">工号：{{data.profile.employeeNo}}</text><text class="person-meta">{{data.profile.department}} · {{data.profile.job}} · 工龄 {{data.profile.years??'未填写'}} 年</text></view><AppIcon name="mountain" :size="48"/></view><view class="hazards"><text class="bold">职业危害接触情况</text><view class="hazard-tags"><text v-if="!data.profile.hazards.length" class="help">后台尚未提供职业危害接触信息</text><text v-for="h in data.profile.hazards" :key="h" class="tag tag-amber">{{h}}</text></view></view><view class="card"><view class="tabs"><view v-for="(t,i) in ['体检报告','健康指标','健康建议','复查随访']" :key="t" :class="{active:active===i}" @tap="active=i">{{t}}</view></view><template v-if="active===0"><view class="section-head"><text class="bold caption">正式归档报告 <text class="green-text">({{data.reports.length}})</text></text><text class="more" @tap="go('/pages/worker/reports/index')">全部上传 ›</text></view><ReportCard v-for="r in data.reports.slice(0,3)" :key="r.id" :report="r" @select="go('/pages/worker/report-detail/index?id='+encodeURIComponent(r.id)+'&revision='+r.revision)"/><text v-if="!data.reports.length" class="help">暂无正式归档报告。已上传或正在审核的报告，请点击“全部上传”查看；网页版医生审核并归档后才会显示在此。</text></template><template v-if="active===1"><view class="between"><text class="bold">关键指标趋势</text><picker :range="data.trends.map(t=>t.label)" @change="trendIndex=Number(($event as any).detail.value)"><text class="tag">{{data.trends[trendIndex]?.label}}⌄</text></picker></view><text v-if="!data.trends.length" class="help">后台尚未提供指标趋势数据</text><TrendChart v-if="data.trends[trendIndex]" :trend="data.trends[trendIndex]"/><text class="help">单位：{{data.trends[trendIndex]?.unit}}</text></template><template v-if="active===2"><text class="help">健康建议服务尚未接入</text><view v-for="a in data.advice" :key="a.id" class="row" @tap="go('/pages/worker/advice/index')"><AppIcon name="heart-pulse"/><text class="row-label">{{a.title}}</text><AppIcon name="chevron-right" color="gray" :size="16"/></view></template><template v-if="active===3"><text class="help">复查随访服务尚未接入</text><view v-for="f in data.followups" :key="f.id" class="row" @tap="go('/pages/worker/followups/index')"><view class="grow"><text class="bold">{{f.title}}</text><view class="help">{{f.dueDate}} · {{f.status==='pending'?'待复查':f.status==='submitted'?'报告已提交':'已完成'}}</view></view><AppIcon name="chevron-right" color="gray" :size="16"/></view></template></view><view v-if="active===0&&data.trends.length" class="card"><view class="between"><text class="section-title">健康变化，看得见</text><text class="help">{{data.trends[0].label}}</text></view><TrendChart :trend="data.trends[0]"/></view><view class="card"><text class="section-title">基本信息</text><view class="info-line" v-for="(v,k) in {'所属矿区':data.profile.mine,'所属部门':data.profile.department,'班组':data.profile.team,'岗位':data.profile.job,'工龄':data.profile.years===null?'未填写':data.profile.years+'年'}" :key="k"><text>{{k}}</text><text>{{v}}</text></view></view></template></view></PageShell></template>
<style scoped>.archive-person{display:flex;align-items:center;gap:24rpx}.person-name{font-size:36rpx;font-weight:700}.person-meta{font-size:22rpx;color:#89998d;display:block;margin-top:7rpx}.hazards{padding:25rpx 28rpx;background:#e9f6ec;border-radius:22rpx;margin-bottom:24rpx;font-size:27rpx}.hazard-tags{display:flex;gap:16rpx;margin-top:18rpx}.tabs{gap:0;justify-content:space-between}.tabs>view{font-size:24rpx}</style>
